#[path = "before.rs"] mod before;
#[path = "final.rs"] mod after;
fn check(n: f64, old: &mut String, new: &mut String) {
    old.clear(); new.clear();
    before::write_number(old, n); after::write_number(new,n);
    assert!(old==new,"{:016x}: {} != {}",n.to_bits(),old,new);
}
fn main() {
    let mut old=String::with_capacity(350); let mut new=String::with_capacity(350);
    let start=std::time::Instant::now();
    let mut count=0u64;
    // Every positive f32 in the optimized magnitude interval, including integral cases.
    for exponent in 131..150 {
        for mantissa in 0..0x800000u32 {
            let n=f32::from_bits(exponent<<23 | mantissa) as f64;
            check(n,&mut old,&mut new);
            count+=1;
        }
        println!("exponent={} tested={} elapsed={:.2}",exponent,count,start.elapsed().as_secs_f64());
    }
    // Uniform bit samples cover negative values, nonfinite values, underflow,
    // narrow-path bounds and general f64 values that must take the old formatter.
    let mut state=0x2718281831415926u64;
    for _ in 0..1_000_000 {
        state ^= state<<13; state ^= state>>7; state ^= state<<17;
        for n in [f64::from_bits(state), -(f32::from_bits(state as u32) as f64),
            f64::from_bits((f32::from_bits(state as u32) as f64).to_bits().wrapping_add(1))] {
            check(n,&mut old,&mut new); count+=1;
        }
    }
    println!("PASS {} values in {:.2}s",count,start.elapsed().as_secs_f64());
}
